from hypothesis import strategies as st


@st.composite
def gen(draw):
    alphabet = draw(st.sampled_from(["abc", "abcxyz", "abcdefghijklmnopqrstuvwxyz", "nrtx"]))
    n = draw(st.integers(3, 10))
    s = draw(st.text(alphabet=alphabet, min_size=n, max_size=n))
    mode = draw(st.integers(0, 2))
    if mode == 0:
        # three letters drawn from S (likely Yes)
        idx = draw(st.lists(st.integers(0, n - 1), min_size=3, max_size=3))
        t = "".join(s[i] for i in idx).upper()
    elif mode == 1:
        # two letters from S followed by X (likely Yes)
        idx = draw(st.lists(st.integers(0, n - 1), min_size=2, max_size=2))
        t = "".join(s[i] for i in idx).upper() + "X"
    else:
        # arbitrary uppercase code over the same letter pool
        letters = draw(st.text(alphabet=alphabet + "X".lower(), min_size=3, max_size=3))
        t = letters.upper()
    return f"{s}\n{t}\n"


def validate(inp):
    lines = inp.split("\n")
    # strip trailing empty lines produced by formatting
    while lines and lines[-1] == "":
        lines.pop()
    if len(lines) != 2:
        return False
    s, t = lines[0], lines[1]
    if not (3 <= len(s) <= 10**5 and s.isalpha() and s.islower() and s.isascii()):
        return False
    if not (len(t) == 3 and t.isalpha() and t.isupper() and t.isascii()):
        return False
    return True


def _is_subseq(p, s):
    it = iter(s)
    return all(c in it for c in p)


def ref(inp):
    lines = inp.split("\n")
    s = lines[0].strip()
    t = lines[1].strip()
    low = t.lower()
    if _is_subseq(low, s):
        return "Yes\n"
    if t[2] == "X" and _is_subseq(low[:2], s):
        return "Yes\n"
    return "No\n"
