from itertools import combinations
from hypothesis import strategies as st

@st.composite
def gen(draw):
    alpha_s = draw(st.sampled_from(["abc", "abx", "xyz", "ab"]))
    n = draw(st.integers(3, 8))
    S = draw(st.text(alphabet=alpha_s, min_size=n, max_size=n))
    mode = draw(st.integers(0, 2))
    if mode == 0:
        # T derived from a random subsequence of S (uppercased)
        idx = sorted(draw(st.lists(st.integers(0, n - 1), min_size=3, max_size=3, unique=True)))
        T = "".join(S[i] for i in idx).upper()
    elif mode == 1:
        # two-letter subsequence plus X
        idx = sorted(draw(st.lists(st.integers(0, n - 1), min_size=2, max_size=2, unique=True)))
        T = "".join(S[i] for i in idx).upper() + "X"
    else:
        T = draw(st.text(alphabet="ABCXYZ", min_size=3, max_size=3))
    return f"{S}\n{T}\n"

def validate(inp):
    lines = inp.split("\n")
    toks = inp.split()
    if len(toks) != 2:
        return False
    S, T = toks
    if not (3 <= len(S) <= 10**5):
        return False
    if not all("a" <= c <= "z" for c in S):
        return False
    if len(T) != 3:
        return False
    if not all("A" <= c <= "Z" for c in T):
        return False
    return True

def ref(inp):
    S, T = inp.split()
    n = len(S)
    low = T.lower()
    # Option 1: all three letters form a subsequence of S
    for i, j, k in combinations(range(n), 3):
        if S[i] == low[0] and S[j] == low[1] and S[k] == low[2]:
            return "Yes"
    # Option 2: first two letters form a subsequence and third letter is X
    if T[2] == "X":
        for i, j in combinations(range(n), 2):
            if S[i] == low[0] and S[j] == low[1]:
                return "Yes"
    return "No"
